inline std::string_view tariffNoticeMessageKeyName(TariffNoticeMessageKey key){
    static constexpr std::array<std::string_view,tariffNoticeMessageKeyCount> names={{"tariff.notice.input_rejected","tariff.notice.integer_only","tariff.notice.draft_only","tariff.notice.too_long","tariff.notice.ascii_only","tariff.notice.removed","tariff.notice.saved_offline","tariff.notice.save_unavailable","tariff.notice.capacity","tariff.notice.added_blank","tariff.notice.fixed_contract"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage tariffNoticeMessage(std::string_view language,TariffNoticeMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=tariffNoticeMessageKeyCount)return {};
    const auto &source=tariffNoticeLocalePacks()[0];const auto *selected=&source;for(const auto &pack:tariffNoticeLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string tariffNoticeEnglish(TariffNoticeMessageKey key){return std::string(tariffNoticeMessage("en",key).text);}
